We seek an approximation to $\Delta_{\mathbb{M}}f$ at $\mathbf{x}_1$ that involves a linear combination of the values of $f$ over the stencil $P_1$ of the form
\begin{align} 
(\Delta_{\mathbb{M}}f)\bigr|_{\mathbf{x}=\mathbf{x}_1} \approx \sum_{j=1}^{n} w_j f(\mathbf{x}_j).
\label{eq:fd_weights}
\end{align}

\begin{align} 
(\Delta_{\mathbb{M}}f)\bigr|_{\mathbf{x}=\mathbf{x}_1} \approx \sum_{j=1}^{n} w_j f(\mathbf{x}_j).
\label{eq:fd_weights}
\end{align}

The first step to computing the RBF-FD weights is to construct an RBF interpolant of $f$ similar to Equation \eqref{eq:srbfinterp}, but now only over the nodes in $P_1$, \emph{i.e.}

\begin{align}
I_{\phi}f(\mathbf{x}) = \sum_{j=1}^n c_j\phi(r_j(\mathbf{x})) + c_{n+1},
\label{eq:f_interp}
\end{align}

where $r_j(\mathbf{x}) = \|\mathbf{x}-\mathbf{x}_j\|$.  The interpolation coefficients $c_j$ can be determined by the solution to the system of equations given in Equation \eqref{eq:rbf_linsys}, but with $X$ replaced with $P_1$;  we denote this system by $A_{P_1} c_f = f_{P_1}$.   Second, we compute the surface gradient of the above interpolant using Equation \eqref{eq:grad} and evaluate it at the nodes in $P_1$.  In the case of the ${ \mathcal G}^x$ component of the gradient, this is given as

\begin{align}
\left( { \mathcal G}^x I_{\phi}f(\mathbf{x}) \right)\bigr|_{\mathbf{x} = \mathbf{x}_i} = \sum_{j=1}^n c_j \underbrace{\left({ \mathcal G}^x \phi(r_j(\mathbf{x})) \right)\bigr|_{\mathbf{x}=\mathbf{x}_i}}_{{\left(B^x_{P_1}\right)}_{i,j}}\; , i=1,\ldots,n,
\label{eq:grad_x_f_interp}
\end{align}

where the constant term from Equation \eqref{eq:f_interp} has vanished since its gradient is zero.  We can rewrite Equation \eqref{eq:grad_x_f_interp} in matrix-vector form using the fact that $c_f = A_{P_1}^{-1} f_{P_1}$ as follows:
\begin{align}
\left( { \mathcal G}^x I_{\phi}f \right)\bigr|_{P_1} = B^x_{P_1} c_f = \left(B^x_{P_1} A^{-1}_{P_1}\right)f_{P_1} = G_{P_1}^x f_{P_1}.
\end{align}

\begin{align}
I_{\phi}f(\mathbf{x}) = \sum_{j=1}^n c_j\phi(r_j(\mathbf{x})) + c_{n+1},
\label{eq:f_interp}
\end{align}

\begin{align}
\left( { \mathcal G}^x I_{\phi}f(\mathbf{x}) \right)\bigr|_{\mathbf{x} = \mathbf{x}_i} = \sum_{j=1}^n c_j \underbrace{\left({ \mathcal G}^x \phi(r_j(\mathbf{x})) \right)\bigr|_{\mathbf{x}=\mathbf{x}_i}}_{{\left(B^x_{P_1}\right)}_{i,j}}\; , i=1,\ldots,n,
\label{eq:grad_x_f_interp}
\end{align}

\begin{align}
\left( { \mathcal G}^x I_{\phi}f \right)\bigr|_{P_1} = B^x_{P_1} c_f = \left(B^x_{P_1} A^{-1}_{P_1}\right)f_{P_1} = G_{P_1}^x f_{P_1}.
\end{align}

Similar approximations can be obtained to the $y$- and $z$-components of the surface gradient operator on this stencil as follows:

\begin{align}
\left( { \mathcal G}^y I_{\phi}f \right)\bigr|_{P_1} = \left(B^y_{P_1} A^{-1}_{P_1}\right)f_{P_1} = G_{P_1}^y f_{P_1}, \\
\left( { \mathcal G}^z I_{\phi}f \right)\bigr|_{P_1} = \left(B^z_{P_1} A^{-1}_{P_1}\right)f_{P_1} = G_{P_1}^z f_{P_1},
\end{align}

where the entries of $B^y_{P_1}$ and $B^z_{P_1}$ are given as

\begin{align*}
(B^y_{P_1})_{i,j} = \left({ \mathcal G}^y \phi(r_j(\mathbf{x}))\right)\bigr|_{\mathbf{x}=\mathbf{x}_i} \; \text{and}\; (B^z_{P_1})_{i,j} = \left({ \mathcal G}^z \phi(r_j(\mathbf{x}))\right)\bigr|_{\mathbf{x}=\mathbf{x}_i}.
\end{align*}

\begin{align}
\left( { \mathcal G}^y I_{\phi}f \right)\bigr|_{P_1} = \left(B^y_{P_1} A^{-1}_{P_1}\right)f_{P_1} = G_{P_1}^y f_{P_1}, \\
\left( { \mathcal G}^z I_{\phi}f \right)\bigr|_{P_1} = \left(B^z_{P_1} A^{-1}_{P_1}\right)f_{P_1} = G_{P_1}^z f_{P_1},
\end{align}

\begin{align*}
(B^y_{P_1})_{i,j} = \left({ \mathcal G}^y \phi(r_j(\mathbf{x}))\right)\bigr|_{\mathbf{x}=\mathbf{x}_i} \; \text{and}\; (B^z_{P_1})_{i,j} = \left({ \mathcal G}^z \phi(r_j(\mathbf{x}))\right)\bigr|_{\mathbf{x}=\mathbf{x}_i}.
\end{align*}

\begin{align}
\left(\Delta_{\mathbb{M}} f\right)\bigr|_{P_1} \approx \underbrace{\left(G_{P_1}^x G_{P_1}^x + G_{P_1}^y G_{P_1}^y + G_{P_1}^z G_{P_1}^z \right)}_{L_{P_1}}f_{P_1}.
\label{eq:surface_lap_P1}
\end{align}

