We consider the torus given by the implicit equation:
\begin{align*}
\mathbb{T}^2 = \left\{\mathbf{x} = (x,y,z) \in \mathbb{R}^3 \;\left| \left(1 - \sqrt{x^2 + y^2}\right)^2 + z^2 - \frac{1}{9} = 0 \right. \right\},
\end{align*}
which can be parameterized using intrinsic coordinates $\varphi$ and $\lambda$ as follows:
\begin{align}
x = \left( 1 + \frac{1}{3}\cos(\varphi)\right)\cos(\lambda),\;  y = \left( 1 + \frac{1}{3}\cos(\varphi)\right)\sin(\lambda),\; z = \frac{1}{3}\sin(\varphi),
\label{eq:torus}
\end{align}
where $-\pi\leq \varphi,\lambda\leq \pi$.

\begin{align*}
\mathbb{T}^2 = \left\{\mathbf{x} = (x,y,z) \in \mathbb{R}^3 \;\left| \left(1 - \sqrt{x^2 + y^2}\right)^2 + z^2 - \frac{1}{9} = 0 \right. \right\},
\end{align*}

\begin{align}
x = \left( 1 + \frac{1}{3}\cos(\varphi)\right)\cos(\lambda),\;  y = \left( 1 + \frac{1}{3}\cos(\varphi)\right)\sin(\lambda),\; z = \frac{1}{3}\sin(\varphi),
\label{eq:torus}
\end{align}

The surface Laplacian of a scalar function $f:\mathbb{T}\rightarrow\mathbb{R}$ in this intrinsic coordinate system is given as
\begin{align*}
\Delta_{\mathbb{M}} f(\varphi,\lambda) = \frac{1}{\left( 1 + \frac{1}{3}\cos(\varphi)\right)^2} \frac{\partial^2 f}{\partial \lambda^2} + \frac{9}{\left( 1 + \frac{1}{3}\cos(\varphi)\right)}  \frac{\partial}{\partial \varphi}\left(\left( 1 + \frac{1}{3}\cos(\varphi)\right)\frac{\partial f}{\partial \varphi}\right).
\end{align*}

\begin{align*}
\Delta_{\mathbb{M}} f(\varphi,\lambda) = \frac{1}{\left( 1 + \frac{1}{3}\cos(\varphi)\right)^2} \frac{\partial^2 f}{\partial \lambda^2} + \frac{9}{\left( 1 + \frac{1}{3}\cos(\varphi)\right)}  \frac{\partial}{\partial \varphi}\left(\left( 1 + \frac{1}{3}\cos(\varphi)\right)\frac{\partial f}{\partial \varphi}\right).
\end{align*}

